// Independent reference: Wayland 1.22.0 cursor/cursor-data.h, left_ptr (10x16, hotspot 1,1).
// https://raw.githubusercontent.com/wayland-mirror/wayland/1.22.0/cursor/cursor-data.h
// Header SHA256 cb9f692118c2fd3f817d43372d3c532db76417d4ea77583f84e63453fcd69a92.
// These 640 little-endian ARGB bytes occur at offset 16328 in the pinned guest's
// /usr/lib/libwayland-cursor.so.0.22.0, SHA256
// 42c23debcace47e501ab1f6f01e94a1ce2ebc777fa26e5396c4f6b0770ce664b.
// Pixel SHA256 03569147f5dd6d3174a5d88c11ae2e1c353a1cd81b4e3987f043225d111cd44f.
// No value here is generated by the pointer bridge or inferred from its output.
export const LEFT_PTR = Object.freeze([
  "WW........", "WKW.......", "WKKW......", "WKKKW.....",
  "WKKKKW....", "WKKKKKW...", "WKKKKKKW..", "WKKKKKKKW.",
  "WKKKKKKKKW", "WKKKKKWWWW", "WKKWKKW...", "WKW.WKKW..",
  "WW..WKKW..", ".....WKKW.", ".....WKKW.", "......WW..",
]);

/** Match the actual rendered arrow, then add the independently specified 1,1 hotspot. */
export function findGuestCursor(bytes, width, height, near, radius = 3) {
  const matches = [];
  for (let y = near.y - radius; y <= near.y + radius; y++) {
    for (let x = near.x - radius; x <= near.x + radius; x++) {
      let count = 0, mismatch = false;
      for (let row = 0; row < LEFT_PTR.length && !mismatch; row++) {
        for (let col = 0; col < LEFT_PTR[row].length; col++) {
          const color = LEFT_PTR[row][col];
          if (color === ".") continue;
          const px = x - 1 + col, py = y - 1 + row;
          if (px < 0 || px >= width || py < 0 || py >= height) continue;
          const offset = (py * width + px) * 4, expected = color === "W" ? 255 : 0;
          if ([0, 1, 2].some((channel) => Math.abs(bytes[offset + channel] - expected) > 8)) {
            mismatch = true;
            break;
          }
          count++;
        }
      }
      if (!mismatch && count >= 80) matches.push({ x, y, hotX: 1, hotY: 1, matchedPixels: count });
    }
  }
  return matches.length === 1 ? matches[0] : null;
}
